// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.brain.persona/** * NOUS — Persona definition. * * Full implementation lives in :feature:persona (Module 7). Brain only needs: * identity, system prompt template, skill preferences, response style, and * optional voice profile. * * BrainPreProcessor substitutes placeholders in [systemPromptTemplate] before * passing to LLM: *   - {{user_name}} → UserContext.displayName *   - {{time}} → BrainContext.timestamp *   - {{location}} → AmbientSnapshot.locationSummary *   - {{persona_name}} → displayName * * @see <a href="docs/spec/module2-spec-review.pdf">§3.6 Persona</a> */data class Persona(    /** Unique persona ID (e.g., "jarvis", "friday", "ultron"). */    val id: String,    /** Human-readable name (shown in UI). */    val displayName: String,    /** System prompt template with placeholders. */    val systemPromptTemplate: String,    /** Per-skill preference weights (0.0-1.0). Higher = preferred. */    val skillPreferences: Map<String, Float>,    /** Response style — tone, verbosity, vocabulary. */    val responseStyle: ResponseStyle,    /** Optional voice profile (TTS params, Module 5). */    val voiceProfile: VoiceProfile? = null,    /** Whether this persona is the default on first launch. */    val isDefault: Boolean = false,    /** Whether this persona is enabled (user can disable non-default). */    val isEnabled: Boolean = true,)/** * Persona response style. */data class ResponseStyle(    val tone: Tone,    val verbosity: Verbosity,    val useEmoji: Boolean,    val vocabulary: Vocabulary,)enum class Tone {    WITTY,        // JARVIS — British, dry humor    FORMAL,       // VISION — synthetic, gentle, deep    TACTICAL,     // EDITH — military-style    GENTLE,       // TADASHI — mentor-like    COLD,         // ULTRON — calculating, philosophical    WARM,         // FRIDAY — Irish, sharp    CALM,         // RESCUE — emergency response, decisive    FRIENDLY,     // KAREN — teen-mentor}enum class Verbosity {    TERSE,        // short, direct    BALANCED,     // medium length    VERBOSE,      // detailed, explanatory}enum class Vocabulary {    SIMPLE,       // everyday words    TECHNICAL,    // jargon-friendly    PHILOSOPHICAL,// deep, abstract}/** * Voice profile — TTS parameters. * * Full implementation in :feature:voice (Module 5). Brain only needs * identity for TTS engine selection. */data class VoiceProfile(    val voiceId: String,    val pitch: Float = 1.0f,        // 0.5 - 2.0    val rate: Float = 1.0f,         // 0.5 - 2.0    val prosody: ProsodyProfile,)data class ProsodyProfile(    val happiness: Float = 0.5f,    val sadness: Float = 0.0f,    val urgency: Float = 0.0f,    val calmness: Float = 0.5f,)